def _convert_columns(schema_editor, convert, needs_convert):
    """COLUMNS の文字を1件ずつ convert（暗号化か、元に戻す）する。needs_convert が False のものはとばす。"""
    connection = schema_editor.connection
    quote = connection.ops.quote_name  # 表や列の名前を、SQL の中で安全に書くための囲み
